CREATE TABLE IF NOT EXISTS organizations(id INTEGER PRIMARY KEY, name TEXT NOT NULL, created TEXT NOT NULL, retention_days INTEGER NOT NULL DEFAULT 365);
CREATE TABLE IF NOT EXISTS memberships(org_id INTEGER REFERENCES organizations(id), user_id INTEGER REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','admin','analyst','viewer')), PRIMARY KEY(org_id,user_id));
CREATE TABLE IF NOT EXISTS incidents(id INTEGER PRIMARY KEY, org_id INTEGER NOT NULL REFERENCES organizations(id), number TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL, severity INTEGER NOT NULL CHECK(severity BETWEEN 1 AND 5), status TEXT NOT NULL, assigned_to INTEGER REFERENCES users(id), created TEXT NOT NULL, updated TEXT NOT NULL, due TEXT, acknowledged TEXT, resolved TEXT, root_cause TEXT NOT NULL DEFAULT '', resolution TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS incidents_org ON incidents(org_id,created);
CREATE TABLE IF NOT EXISTS incident_events(id INTEGER PRIMARY KEY, org_id INTEGER NOT NULL REFERENCES organizations(id), incident_id INTEGER NOT NULL REFERENCES incidents(id), actor_id INTEGER REFERENCES users(id), kind TEXT NOT NULL, message TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assets(id INTEGER PRIMARY KEY, org_id INTEGER NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, type TEXT NOT NULL, owner TEXT NOT NULL DEFAULT '', criticality TEXT NOT NULL, environment TEXT NOT NULL, identifiers TEXT NOT NULL DEFAULT '', created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS assets_org ON assets(org_id);
CREATE TABLE IF NOT EXISTS incident_assets(org_id INTEGER NOT NULL REFERENCES organizations(id), incident_id INTEGER REFERENCES incidents(id), asset_id INTEGER REFERENCES assets(id), PRIMARY KEY(incident_id,asset_id));
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY, org_id INTEGER NOT NULL REFERENCES organizations(id), incident_id INTEGER REFERENCES incidents(id), title TEXT NOT NULL, assigned_to INTEGER REFERENCES users(id), status TEXT NOT NULL DEFAULT 'To do', due TEXT, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS indicators(id INTEGER PRIMARY KEY, org_id INTEGER NOT NULL REFERENCES organizations(id), incident_id INTEGER NOT NULL REFERENCES incidents(id), type TEXT NOT NULL, value TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence(id INTEGER PRIMARY KEY, org_id INTEGER NOT NULL REFERENCES organizations(id), incident_id INTEGER NOT NULL REFERENCES incidents(id), filename TEXT NOT NULL, storage_key TEXT NOT NULL UNIQUE, mime TEXT NOT NULL, size INTEGER NOT NULL, sha256 TEXT NOT NULL, scan_status TEXT NOT NULL, uploaded_by INTEGER REFERENCES users(id), created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS custody(id INTEGER PRIMARY KEY, org_id INTEGER NOT NULL REFERENCES organizations(id), evidence_id INTEGER NOT NULL REFERENCES evidence(id), actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY, org_id INTEGER NOT NULL REFERENCES organizations(id), actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, resource TEXT NOT NULL, created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_org ON audit_logs(org_id,id);
CREATE TABLE IF NOT EXISTS invitations(id INTEGER PRIMARY KEY, org_id INTEGER NOT NULL REFERENCES organizations(id), email TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','analyst','viewer')), token_hash TEXT NOT NULL UNIQUE, expires INTEGER NOT NULL, accepted INTEGER NOT NULL DEFAULT 0, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS account_tokens(token_hash TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id), kind TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notification_preferences(org_id INTEGER REFERENCES organizations(id), user_id INTEGER REFERENCES users(id), incident_updates INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(org_id,user_id));
CREATE TABLE IF NOT EXISTS subscriptions(org_id INTEGER PRIMARY KEY REFERENCES organizations(id), plan TEXT NOT NULL DEFAULT 'Unconfigured', status TEXT NOT NULL DEFAULT 'No billing provider connected', provider_customer TEXT);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset INTEGER NOT NULL);
